import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        ArrayList<Integer> input = new ArrayList<>();
        while (scanner.hasNextInt()) { input.add(scanner.nextInt()); }
        int[] a = input.stream().mapToInt(Integer::intValue).toArray();
        int[] dp = new int[k + 1];
        Arrays.fill(dp, 1000000);
        dp[0] = 0;
        for (int amount = 1; amount <= k; amount++) {
            for (int i = 0; i < n; i++) {
                if (a[i] <= amount) {
                    dp[amount] = Math.min(dp[amount], dp[amount - a[i]] + 1);
                }
            }
        }
        int answer = dp[k];
        if (answer >= 1000000) {
            answer = -1;
        }
        System.out.println(answer);
    }
}

