import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        ArrayList<Integer> input = new ArrayList<>();
        while (scanner.hasNextInt()) { input.add(scanner.nextInt()); }
        int[] a = input.stream().mapToInt(Integer::intValue).toArray();
        int[] distance = new int[n];
        Arrays.fill(distance, 1000000000);
        int[] used = new int[n];
        Arrays.fill(used, 0);
        distance[k] = 0;
        for (int step = 0; step < n; step++) {
            int vertex = -1;
            for (int i = 0; i < n; i++) {
                if (used[i] == 0) {
                    if (vertex == -1 || distance[i] < distance[vertex]) {
                        vertex = i;
                    }
                }
            }
            if (vertex == -1 || distance[vertex] == 1000000000) {
                break;
            }
            used[vertex] = 1;
            for (int next = 0; next < n; next++) {
                int weight = a[vertex * n + next];
                if (weight >= 0 && used[next] == 0) {
                    distance[next] = Math.min(distance[next], distance[vertex] + weight);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            int value = distance[i];
            if (value == 1000000000) {
                value = -1;
            }
            System.out.println(value);
        }
    }
}

